-- supabase/seed.sql
-- Complete seed data: Knowledge Cards for Chapters 2-7 and Questions for all 7 Chapters
-- NOTE: Chapters and Chapter 1 knowledge cards are inserted via the migration file (001_initial_schema.sql).

-- ============================================
-- KNOWLEDGE CARDS: Chapter 2 (Appointment and Qualifications) — 6 cards
-- ============================================

INSERT INTO knowledge_cards (chapter_id, title, content, key_points, sort_order, source_label, source_url) VALUES
(2, 'Eligibility Requirements for a California Notary Commission', 'To qualify for appointment as a notary public in California, an applicant must meet several statutory requirements. The applicant must be at least 18 years of age and a legal resident of California at the time of appointment. There is no citizenship requirement—lawful permanent residents (green card holders) are eligible. The applicant must not have been convicted of a felony or any crime involving moral turpitude, dishonesty, or deceit. A prior felony conviction is disqualifying unless the applicant''s civil and firearm rights have been fully restored in the jurisdiction of conviction.', ARRAY['At least 18 years old', 'Must be a legal resident of California', 'No citizenship requirement—green card holders eligible', 'No disqualifying criminal convictions', 'Felony conviction disqualifies unless rights restored'], 1, 'CA Secretary of State Notary Public Handbook (2025), Section 2', 'https://www.sos.ca.gov/notary'),

(2, 'The Six-Hour Course of Study Requirement', 'Every person applying for a new notary public commission must complete a six-hour course of study prescribed by the California Secretary of State. The course covers notary law, procedures, and ethics, including proper identification of signers, journal requirements, and the types of notarial acts. The course must be completed within six months before the date of the notary public examination. Proof of completion—typically a certificate from a qualified education provider—must be presented at the examination site. Failure to present a valid course completion certificate will result in the applicant being denied admission to the exam.', ARRAY['Six-hour statutorily required course for new commission', 'Covers law, procedures, and ethics', 'Must be completed within six months before exam', 'Certificate must be presented at exam site', 'Without certificate, admission to exam is denied'], 2, 'CA Government Code Section 8201.1, CA Secretary of State Notary Public Handbook (2025), Section 2', 'https://www.sos.ca.gov/notary'),

(2, 'Live Scan Fingerprinting and Background Check', 'All applicants for a notary public commission must undergo a criminal background check through the California Department of Justice (DOJ) and the Federal Bureau of Investigation (FBI). The applicant must submit their fingerprints electronically via Live Scan, a statewide digital fingerprint imaging system. The Live Scan must be completed before the notary examination. The Secretary of State will review the background check results when determining whether the applicant meets the good moral character requirement. Applicants are responsible for paying the fingerprint processing fees, which are separate from the examination fee.', ARRAY['Background check required via Live Scan', 'Checks CA DOJ and FBI records', 'Must be completed before the examination', 'Secretary of State reviews results for character assessment', 'Applicant pays separate processing fees'], 3, 'CA Government Code Section 8201.5, CA Secretary of State Notary Public Handbook (2025), Section 2', 'https://www.sos.ca.gov/notary'),

(2, 'The $15,000 Surety Bond Requirement', 'Every California notary public must file a $15,000 surety bond with the county clerk before receiving their commission. The bond is not insurance for the notary—it protects the public against financial loss caused by the notary''s misconduct or negligence in performing notarial duties. The notary must purchase the bond from a surety company licensed to do business in California. The bond must remain in effect for the entire four-year commission term. If the bond is cancelled or lapses, the notary''s commission is automatically suspended until a new bond is filed. The notary is personally liable to the surety company for any amounts the surety pays out on a claim.', ARRAY['$15,000 surety bond required for all CA notaries', 'Protects the public, not the notary', 'Must be purchased from a licensed surety company', 'Must remain in effect for full 4-year term', 'Commission suspended if bond lapses', 'Notary is personally liable to surety for claims paid'], 4, 'CA Government Code Sections 8212-8213, CA Secretary of State Notary Public Handbook (2025), Section 2', 'https://www.sos.ca.gov/notary'),

(2, 'Filing the Oath and Bond with the County Clerk', 'After passing the examination and receiving a commission from the Secretary of State, the new notary must file their oath of office and $15,000 surety bond with the county clerk''s office in the county where the notary maintains their principal place of business. This filing must occur within thirty calendar days of the commission''s start date—the date shown on the commission certificate. The county clerk administers the oath, and the notary must sign the oath in the clerk''s presence. Failure to file within the thirty-day window voids the commission, requiring the applicant to begin the entire process again, including re-taking the six-hour course and examination.', ARRAY['Oath and bond filed with county clerk', 'Must be filed within 30 calendar days of commission start date', 'County clerk administers the oath', 'Notary signs oath in clerk''s presence', 'Failure to file within 30 days voids the commission', 'Late filing requires re-starting the entire process'], 5, 'CA Government Code Sections 8203-8204, CA Secretary of State Notary Public Handbook (2025), Section 2', 'https://www.sos.ca.gov/notary'),

(2, 'Commission Term and Renewal Process', 'A California notary public commission is valid for a term of four years from the date specified on the commission certificate. Notaries may apply for reappointment by completing the entire qualification process again—there is no automatic renewal or simple fee renewal. The reappointment process requires: completing a new three-hour refresher course (instead of the six-hour course required for new applicants), passing the written examination again, undergoing a new Live Scan background check, and obtaining a new $15,000 surety bond. If the notary''s previous commission has already expired, the full six-hour course must be taken instead of the three-hour refresher.', ARRAY['Commission term is exactly four years', 'No automatic renewal—full reappointment required', 'Reappointment requires 3-hour refresher course', 'Must re-take and pass the written examination', 'New Live Scan background check required', 'New $15,000 surety bond required', 'Expired commission requires repeating 6-hour course'], 6, 'CA Government Code Sections 8202, 8201.1, CA Secretary of State Notary Public Handbook (2025), Section 2', 'https://www.sos.ca.gov/notary');

-- ============================================
-- KNOWLEDGE CARDS: Chapter 3 (Jurisdiction and Geographic Authority) — 5 cards
-- ============================================

INSERT INTO knowledge_cards (chapter_id, title, content, key_points, sort_order, source_label, source_url) VALUES
(3, 'California Statewide Jurisdiction', 'A California notary public has jurisdiction to perform notarial acts anywhere within the geographic boundaries of the State of California. The notary''s commission is issued by the Secretary of State, granting the notary the authority to act in all 58 counties. However, the oath of office and surety bond are filed in the county where the notary maintains their principal place of business. Even if a notary relocates to a different county during the commission term, they remain authorized to act statewide without re-filing. The notary must, however, notify the Secretary of State of any change of address within 30 days.', ARRAY['Jurisdiction extends throughout entire State of California', 'Notary can act in all 58 counties', 'Commission is granted by the Secretary of State', 'Oath and bond filed in principal place of business county', 'Relocation within CA does not require re-filing', 'Must notify Secretary of State of address change within 30 days'], 1, 'CA Government Code Section 8225, CA Secretary of State Notary Public Handbook (2025), Section 3', 'https://www.sos.ca.gov/notary'),

(3, 'Where a California Notary Can and Cannot Act', 'A California notary public is strictly limited to performing notarial acts within the borders of California. A California notary cannot notarize documents in any other state, even if the document will be filed or used in California. Additionally, a notary commissioned only in California cannot perform acts while physically located in another state, territory, or country. The notarial act is governed by the law of the jurisdiction where the notary is physically located at the time of the act—not where the document originates or where it will be used. This means a California notary vacationing in another state cannot legally perform notarial acts while there.', ARRAY['California notary can only act within CA borders', 'Cannot notarize while physically in another state', 'Document destination does not determine jurisdiction', 'Location of the notary at time of act controls', 'Vacation or travel to another state suspends authority'], 2, 'CA Secretary of State Notary Public Handbook (2025), Section 3', 'https://www.sos.ca.gov/notary'),

(3, 'Cross-State Document Recognition', 'A document notarized by a California notary public within California is generally recognized as valid in other states under principles of comity and the Full Faith and Credit Clause of the U.S. Constitution. Similarly, California generally recognizes notarial acts performed by notaries commissioned in other states, provided those acts were performed within that notary''s home state jurisdiction and comply with that state''s laws. However, each state has its own requirements for what constitutes a valid notarization, and a document intended for use in another state should be prepared with that state''s requirements in mind. When a document is intended for use outside the United States, an apostille or authentication certificate from the California Secretary of State may also be required.', ARRAY['CA notarizations generally recognized in other states', 'Full Faith and Credit Clause supports interstate recognition', 'CA recognizes valid out-of-state notarizations', 'Foreign-state requirements may differ from CA rules', 'Apostille may be needed for international document use'], 3, 'CA Secretary of State Notary Public Handbook (2025), Section 3', 'https://www.sos.ca.gov/notary'),

(3, 'Notarizing Out-of-State Documents in California', 'A California notary may notarize a document that will be used or filed in another state, so long as the notary and the signer are both physically present in California at the time of the notarization. The notary must follow California notarial law and use the California certificate wording for the specific notarial act being performed. However, if the receiving state requires a different certificate form, the notary may attach a loose certificate that complies with California law. The notary should never use an out-of-state certificate form that conflicts with California requirements. If in doubt, the notary should use the California certificate form and let the receiving state determine acceptability.', ARRAY['Can notarize out-of-state documents while in CA', 'Notary and signer must both be physically in California', 'Must follow California notarial law and certificate wording', 'Loose California certificate may be attached', 'Never use out-of-state form that conflicts with CA law'], 4, 'CA Secretary of State Notary Public Handbook (2025), Section 3', 'https://www.sos.ca.gov/notary'),

(3, 'Electronic and Remote Notarization in California', 'California law authorizes traditional paper-based notarization and has also established a framework for electronic notarization. In electronic notarization, the notary uses an electronic signature and an electronic seal, but both parties are still physically present in the same room. California also permits remote online notarization (RON) under specific statutory authority, where the signer appears via audio-visual communication technology rather than in person. Remote notarization requires the notary to use technology platforms that meet statutory requirements for identity proofing, credential analysis, and tamper-evident recording. The Secretary of State has established specific requirements for notaries seeking authorization to perform remote notarizations, including additional registration and the use of technology vendors meeting statutory requirements.', ARRAY['CA authorizes traditional and electronic notarization', 'Electronic notarization still requires physical presence', 'Remote online notarization (RON) authorized under statute', 'RON uses audio-visual technology for signer appearance', 'Technology platform meeting statutory requirements for RON', 'Additional registration required for remote notarization'], 5, 'CA Secretary of State Notary Public Handbook (2025), Section 3', 'https://www.sos.ca.gov/notary');

-- ============================================
-- KNOWLEDGE CARDS: Chapter 4 (Types of Notarial Acts) — 7 cards
-- ============================================

INSERT INTO knowledge_cards (chapter_id, title, content, key_points, sort_order, source_label, source_url) VALUES
(4, 'The Acknowledgment', 'An acknowledgment is a notarial act in which the signer personally appears before the notary and acknowledges that they executed (signed) the document voluntarily. The signer does not need to sign the document in the notary''s presence—the signature may already be on the document when the signer appears. The signer simply declares to the notary that the signature is their own and that they signed the document willingly. The notary must positively identify the signer through personal knowledge or satisfactory evidence. The notary then completes a notarial certificate of acknowledgment, which includes the venue (state and county), the date, the signer''s name, and the notary''s signature and seal.', ARRAY['Signer acknowledges existing signature as their own', 'Signer does not need to sign in notary''s presence', 'Signer must declare the signing was voluntary', 'Notary must positively identify the signer', 'Certificate includes venue, date, name, signature, seal', 'Commonly used for deeds, powers of attorney, contracts'], 1, 'CA Government Code Sections 1185, 1189, CA Secretary of State Notary Public Handbook (2025), Section 4', 'https://www.sos.ca.gov/notary'),

(4, 'The Jurat', 'A jurat is a notarial act in which the signer must personally appear before the notary, sign the document in the notary''s presence, and take an oath or affirmation swearing that the contents of the document are true and correct. Unlike an acknowledgment, the document must be signed (or re-signed) in front of the notary. The notary administers an oath or affirmation to the signer, asking them to swear or affirm under penalty of perjury that the statements in the document are true. The notary then completes the jurat certificate, which states that the document was "subscribed and sworn to (or affirmed) before me" on the given date. Jurats are typically required for affidavits, sworn declarations, and depositions.', ARRAY['Signer must sign (or re-sign) in notary''s presence', 'Notary administers an oath or affirmation', 'Signer swears to truth of document contents', 'Notary positively identifies the signer', 'Certificate states "subscribed and sworn to before me"', 'Commonly used for affidavits and sworn declarations'], 2, 'CA Government Code Section 8202, CA Secretary of State Notary Public Handbook (2025), Section 4', 'https://www.sos.ca.gov/notary'),

(4, 'Acknowledgment vs. Jurat: Key Differences', 'Understanding the distinction between an acknowledgment and a jurat is one of the most important concepts for California notaries. An acknowledgment verifies the identity of the signer and confirms that the signer executed the document voluntarily. The signer does not sign in the notary''s presence, and no oath is administered. A jurat, by contrast, requires the signer to sign the document in the notary''s presence and to swear or affirm under penalty of perjury that the document''s contents are true. The core distinction is that a jurat compels truthfulness about the document''s content under oath, while an acknowledgment only confirms that the signature is genuine and voluntary. The notary must never decide which certificate to use—they must ask the signer which act is required. If the signer does not know, the notary should advise the signer to consult the document preparer or an attorney.', ARRAY['Acknowledgment: signer does not sign before notary, no oath', 'Jurat: signer must sign before notary, oath required', 'Acknowledgment confirms voluntary signature', 'Jurat compels truthfulness under penalty of perjury', 'Notary must never choose certificate type for signer', 'If signer is unsure, refer to document preparer or attorney'], 3, 'CA Secretary of State Notary Public Handbook (2025), Section 4', 'https://www.sos.ca.gov/notary'),

(4, 'Administering Oaths and Affirmations', 'A California notary public is authorized to administer oaths and affirmations as an independent notarial act, not just as part of performing a jurat. An oath is a solemn declaration that invokes a supreme being or deity as a witness to the truth of a statement. An affirmation is an equivalent declaration that does not invoke a deity, used by individuals who object to religious oaths. The person taking the oath or affirmation must raise their right hand or perform some other appropriate gesture while the notary administers the oath. The notary may charge the statutory fee for administering an oath or affirmation. Falsely swearing under oath constitutes perjury, which is a felony in California.', ARRAY['Oaths and affirmations authorized as independent acts', 'Oath invokes deity; affirmation does not', 'Affirmation used for those who object to religious oaths', 'Person must raise right hand or make appropriate gesture', 'Notary may charge statutory fee', 'False statements under oath constitute felony perjury'], 4, 'CA Government Code Section 8205, CA Secretary of State Notary Public Handbook (2025), Section 4', 'https://www.sos.ca.gov/notary'),

(4, 'Certified Copy of a Power of Attorney', 'Under California law, a notary public may only certify copies of one specific type of document: a power of attorney. The notary may not certify copies of other documents, such as birth certificates, death certificates, marriage licenses, school transcripts, or passports. To certify a copy of a power of attorney, the signer must present the original document to the notary and request the certification in writing. The notary then compares the copy to the original, confirms they match, and completes a certificate of certified copy of power of attorney. A separate notary public certificate exists for this purpose. Notaries should carefully review this limitation—certifying unauthorized copies can create legal liability and may constitute misconduct.', ARRAY['CA notary can only certify copies of powers of attorney', 'Cannot certify copies of birth certificates or other records', 'Original document must be presented for comparison', 'Signer must request certification in writing', 'Separate notarial certificate exists for this act', 'Unauthorized copy certification creates legal liability'], 5, 'CA Government Code Section 8205, CA Secretary of State Notary Public Handbook (2025), Section 4', 'https://www.sos.ca.gov/notary'),

(4, 'Signature Witnessing', 'Signature witnessing is a notarial act in which the signer must personally appear before the notary and sign the document in the notary''s presence. The notary verifies the signer''s identity and witnesses the actual act of signing. Unlike a jurat, no oath or affirmation is administered, and unlike an acknowledgment, the signature must be made in the notary''s presence. The notary completes a certificate stating that the signer personally appeared and executed the document in the notary''s presence. Signature witnessing is less common than acknowledgments and jurats but may be specifically required by certain documents or by the laws of other jurisdictions. Notaries should use the certificate appropriate to the specific notarial act requested.', ARRAY['Signer must sign document in notary''s presence', 'No oath or affirmation is administered', 'Notary verifies identity and watches the signing', 'Certificate states signer executed document in presence', 'Less common than acknowledgments and jurats', 'Use appropriate certificate for the specific act requested'], 6, 'CA Secretary of State Notary Public Handbook (2025), Section 4', 'https://www.sos.ca.gov/notary'),

(4, 'Protests and Their Limited Use', 'A protest is a formal notarial certificate attesting that a negotiable instrument—such as a check, promissory note, or bill of exchange—was presented for payment or acceptance and was refused. Protests are primarily governed by the Uniform Commercial Code and are most commonly associated with banking and commercial transactions involving dishonored checks. While California notaries are legally authorized to issue protests, this notarial act is rarely performed by general notaries in modern practice, as most financial institutions handle protests through their own internal processes. Notaries who are not familiar with the detailed requirements of the Uniform Commercial Code regarding protests should not attempt to perform this act without additional specialized training.', ARRAY['Formal certificate of dishonor for negotiable instruments', 'Governed by the Uniform Commercial Code', 'Used for checks, promissory notes, bills of exchange', 'Rarely performed by general notaries in practice', 'Most financial institutions handle protests internally', 'Specialized training recommended before performing'], 7, 'CA Secretary of State Notary Public Handbook (2025), Section 4', 'https://www.sos.ca.gov/notary');

-- ============================================
-- KNOWLEDGE CARDS: Chapter 5 (Identifying Document Signers) — 6 cards
-- ============================================

INSERT INTO knowledge_cards (chapter_id, title, content, key_points, sort_order, source_label, source_url) VALUES
(5, 'Personal Knowledge of the Signer', 'A California notary may identify a document signer based on personal knowledge—meaning the notary has direct, firsthand familiarity with the individual that is derived from association in the course of regular dealings. This is the simplest identification method, but it carries risks because the notary bears full responsibility for any error. Personal knowledge means more than a casual acquaintance: the notary must be sufficiently familiar with the person that no reasonable doubt exists about their identity. If the notary has any uncertainty whatsoever, they should not rely on personal knowledge and should instead request satisfactory evidence of identity. The notary should indicate in their journal when identification is based on personal knowledge.', ARRAY['Identification based on firsthand familiarity', 'Notary must know signer through regular dealings', 'Standard: no reasonable doubt about identity', 'Any uncertainty should trigger ID requirement', 'Notary bears full responsibility for errors', 'Journal must note when personal knowledge is used'], 1, 'CA Government Code Section 1185, CA Secretary of State Notary Public Handbook (2025), Section 5', 'https://www.sos.ca.gov/notary'),

(5, 'Satisfactory Evidence: Government-Issued Identification Documents', 'Under California law, "satisfactory evidence" of identity generally means a current identification document issued by a federal, state, county, or municipal government that contains the individual''s photograph, physical description, signature, and an identifying number. The most commonly accepted forms of ID are a California driver''s license, a California identification card issued by the Department of Motor Vehicles, a United States passport, a foreign passport stamped by U.S. immigration authorities, a U.S. military identification card, and an inmate identification card issued by the California Department of Corrections and Rehabilitation for currently incarcerated individuals. The ID must be current or, if recently expired, issued within the past five years. The notary must visually compare the photograph and physical description on the ID to the person appearing before them.', ARRAY['Government-issued ID with photo required', 'Must contain photo, description, signature, and ID number', 'Acceptable: driver''s license, passport, military ID', 'ID must be current (or expired within 5 years)', 'Notary must visually compare photo to the signer', 'Physical description on ID must match the signer'], 2, 'CA Government Code Section 1185, CA Civil Code Section 1185, CA Secretary of State Notary Public Handbook (2025), Section 5', 'https://www.sos.ca.gov/notary'),

(5, 'What Makes an Identification Document Acceptable or Unacceptable', 'For an identification document to be acceptable, it must meet all four statutory criteria: a photograph of the individual, a physical description (height, weight, eye color, hair color), a signature, and a serial or identifying number. The document must be current or, if issued within the past five years, may be recently expired. Identification documents that do not meet these criteria—such as a social security card, a credit or debit card, a birth certificate, a library card, a workplace badge, or a check-cashing card—are not acceptable as primary identification. If the signer does not have an acceptable ID, the notary may use the credible witness procedure. However, the notary may never rely on an ID that they know (or should reasonably know) is fraudulent, altered, or does not belong to the person presenting it.', ARRAY['Must meet all four statutory criteria', 'Photo, physical description, signature, ID number required', 'Document must be current or expired within 5 years', 'Social security cards and birth certificates not acceptable', 'Credit cards, library cards, workplace badges not acceptable', 'Never accept known fraudulent or altered identification'], 3, 'CA Secretary of State Notary Public Handbook (2025), Section 5', 'https://www.sos.ca.gov/notary'),

(5, 'When Identification Is Insufficient', 'Even when a signer presents a government-issued ID that meets the statutory criteria, the notary must still independently assess whether the identification is sufficient. An ID is insufficient if: (1) it has expired more than five years ago; (2) the photograph or physical description does not reasonably match the person appearing before the notary; (3) the ID appears to be altered, defaced, or fraudulent; (4) the signature on the ID does not reasonably match the signature provided by the signer; or (5) the notary has reason to believe the ID does not belong to the person presenting it. If any of these conditions exist, the notary must refuse to proceed with the notarization based on that ID. The notary may then offer the signer the option of providing another acceptable ID or using the credible witness procedure.', ARRAY['Expired more than 5 years: insufficient', 'Photo/description does not match signer: insufficient', 'Altered, defaced, or appears fraudulent: insufficient', 'Signature mismatch: insufficient', 'Notary believes ID does not belong to presenter: insufficient', 'Offer alternative ID or credible witness procedure'], 4, 'CA Secretary of State Notary Public Handbook (2025), Section 5', 'https://www.sos.ca.gov/notary'),

(5, 'The Credible Witness Procedure', 'When a signer lacks acceptable identification, a California notary may use the credible witness procedure to establish identity. Under this procedure, two credible witnesses—or one witness who is personally known to the notary—must appear and swear under oath that the signer is who they claim to be. Credible witnesses must meet the same identification requirements as any signer: the notary must identify each credible witness using either personal knowledge or satisfactory evidence. The credible witness must personally know the signer and be willing to swear to the signer''s identity. The notary must record the names, addresses, and identification details of all credible witnesses in the journal. The credible witness takes an oath, administered by the notary, regarding the truth of their identification of the signer.', ARRAY['Used when signer lacks acceptable identification', 'Two credible witnesses or one personally known to notary', 'Each witness must be identified by the notary', 'Witness must personally know the signer', 'Witness takes an oath regarding signer''s identity', 'Witness names, addresses, and ID details recorded in journal'], 5, 'CA Government Code Section 1185, CA Secretary of State Notary Public Handbook (2025), Section 5', 'https://www.sos.ca.gov/notary'),

(5, 'Identity Proofing for Remote Online Notarization', 'For remote online notarizations (RON), a California notary must use a technology platform that performs identity proofing through a multi-step process. The platform must conduct credential analysis, which uses technology to verify the authenticity of the signer''s government-issued identification by examining security features such as holograms, micro-printing, and data consistency. The platform must also use knowledge-based authentication (KBA), which presents the signer with questions derived from public and private data sources that only the true individual should be able to answer. The entire audio-visual session must be recorded and retained. If either credential analysis or KBA fails or raises concerns, the notary must not proceed with remote notarization of that signer. The notary retains personal responsibility for assessing whether the identity proofing process has been satisfactorily completed.', ARRAY['Multi-step identity proofing required for RON', 'Credential analysis verifies ID authenticity', 'Knowledge-based authentication (KBA) required', 'Audio-visual session must be recorded and retained', 'Failed proofing means notary must not proceed', 'Notary retains responsibility for assessing results'], 6, 'CA Secretary of State Notary Public Handbook (2025), Section 5', 'https://www.sos.ca.gov/notary');

-- ============================================
-- KNOWLEDGE CARDS: Chapter 6 (Record Keeping and Notary Journals) — 6 cards
-- ============================================

INSERT INTO knowledge_cards (chapter_id, title, content, key_points, sort_order, source_label, source_url) VALUES
(6, 'The Sequential Journal Requirement', 'California law requires every notary public to keep a sequential journal of all notarial acts performed. The journal must be a bound, paper journal with pre-numbered pages, or, if the notary has been authorized to use an electronic journal by the Secretary of State, a tamper-evident electronic format. The journal creates a chronological audit trail of the notary''s activity. The notary must make journal entries at the time of the notarial act—not later. A separate entry must be made for each notarial act, even if multiple acts are performed on the same document. The journal is the property of the notary (not the employer) and must be kept in the notary''s exclusive custody and control at all times.', ARRAY['Sequential journal is mandatory for all CA notaries', 'Must be bound paper with pre-numbered pages', 'Electronic journal requires Secretary of State authorization', 'Entries must be made at the time of the act, not later', 'Separate entry per notarial act', 'Journal belongs to notary, not employer'], 1, 'CA Government Code Section 8206, CA Secretary of State Notary Public Handbook (2025), Section 6', 'https://www.sos.ca.gov/notary'),

(6, 'Required Information in Each Journal Entry', 'Each journal entry must contain specific information as required by California law: (1) the date and time of the notarial act; (2) the type of notarial act (acknowledgment, jurat, etc.); (3) the type of document, the date of the document, and the document''s title or description; (4) the printed name and address of the signer; (5) the type of identification used to identify the signer, including the issuing agency, serial or identifying number, and issue and expiration dates of the ID; (6) the signer''s signature in the journal; (7) the fee charged for the notarial act; and (8) if the document is a deed, quitclaim deed, or deed of trust affecting real property, the right thumbprint of the signer. The right thumbprint is required by statute for any instrument affecting real property.', ARRAY['Date and time of the notarial act', 'Type of notarial act performed', 'Document type, date, and title/description', 'Signer printed name and address', 'ID type, issuing agency, serial number, dates', 'Signer''s signature in journal', 'Fee charged', 'Right thumbprint required for deeds and real property documents'], 2, 'CA Government Code Section 8206, CA Secretary of State Notary Public Handbook (2025), Section 6', 'https://www.sos.ca.gov/notary'),

(6, 'Sequential Journals and Page Integrity', 'The notary journal must be a permanently bound volume with pre-numbered pages. Loose-leaf journals, ring binders, or notebooks that allow page removal or insertion are not permitted. The sequential page numbering ensures that entries cannot be removed or pages inserted after the fact, thereby protecting the integrity of the journal. If a line or space within an entry is left blank, the notary should draw a line through the blank space before proceeding to the next entry to prevent unauthorized additions. When a journal volume is completed, the notary must retain the entire volume. No pages should ever be removed from a journal for any reason.', ARRAY['Must be permanently bound with pre-numbered pages', 'Loose-leaf journals or ring binders not permitted', 'Sequential numbering preserves journal integrity', 'Draw line through blank spaces to prevent additions', 'Retain entire completed volume', 'Never remove pages from a journal'], 3, 'CA Secretary of State Notary Public Handbook (2025), Section 6', 'https://www.sos.ca.gov/notary'),

(6, 'Correcting Errors in the Journal', 'If a notary makes an error in a journal entry, the correct method for fixing the error is to draw a single line through the erroneous information, write the correct information in a nearby space or in the margin, and initial the correction. The original, erroneous text must remain legible. A notary must never use correction fluid, white-out, tape, or any other method that obscures or obliterates the original entry. Erasing, writing over, or tearing out a page destroys the integrity of the journal and may be considered evidence of an attempt to conceal misconduct. If the error is discovered at a later date (after the signer has left), the notary should also note the date on which the correction was made.', ARRAY['Draw a single line through the error', 'Write the correction nearby or in the margin', 'Initial each correction', 'Original text must remain legible', 'Never use white-out, correction fluid, or tape', 'Erasing or tearing out pages destroys journal integrity', 'Note the date of later corrections'], 4, 'CA Secretary of State Notary Public Handbook (2025), Section 6', 'https://www.sos.ca.gov/notary'),

(6, 'Journal Retention and Security Requirements', 'A California notary must retain the journal for the duration of their commission and for a reasonable period thereafter. While California law does not specify an exact retention period for paper journals, the recommended practice is to retain journals indefinitely or at least as long as the statutes of limitation for notary-related legal actions may run. The notary must keep all journals in their exclusive custody and control. An employer may not retain or confiscate a notary''s journal, even if the employer paid for the journal. If the notary resigns the commission, retires, or the commission expires without renewal, the notary must deliver all journals to the county clerk in the county where the notary''s oath and bond were filed within 30 days. Journals delivered to the county clerk are then retained according to the county''s records retention schedule.', ARRAY['Retain journal for duration of commission and beyond', 'Keep all journals in notary''s exclusive custody', 'Employer cannot retain or confiscate the journal', 'Upon resignation or expiration: deliver to county clerk', 'Delivery to county clerk must occur within 30 days', 'County retains journals per records retention schedule'], 5, 'CA Government Code Section 8206, CA Secretary of State Notary Public Handbook (2025), Section 6', 'https://www.sos.ca.gov/notary'),

(6, 'Electronic Journals', 'A California notary may keep an electronic journal if the Secretary of State has authorized the specific electronic journal system being used. An electronic journal must be tamper-evident, meaning it must be designed so that any alteration, deletion, or unauthorized entry is detectable. The electronic journal must allow entries to be made at or near the time of the notarial act. It must also be capable of generating a printable copy of the journal upon request. The same information required for a paper journal entry (date, time, type of act, document description, signer identity, ID details, signature, fee, and thumbprint when applicable) must be recorded in the electronic journal. Backups of the electronic journal must be maintained regularly. The notary retains exclusive control over access credentials to the electronic journal—employers may not have sole access.', ARRAY['Electronic journal must be authorized by Secretary of State', 'Must be tamper-evident—alterations must be detectable', 'Entries made at or near time of notarial act', 'Must generate printable copy upon request', 'Same required information as paper journal entries', 'Regular backups must be maintained', 'Notary retains exclusive control over access credentials'], 6, 'CA Secretary of State Notary Public Handbook (2025), Section 6', 'https://www.sos.ca.gov/notary');

-- ============================================
-- KNOWLEDGE CARDS: Chapter 7 (Ethics and Legal Responsibilities) — 7 cards
-- ============================================

INSERT INTO knowledge_cards (chapter_id, title, content, key_points, sort_order, source_label, source_url) VALUES
(7, 'Prohibited Acts for California Notaries', 'California law identifies several acts that notaries are strictly prohibited from performing. These include: (1) notarizing any document in which the notary has a direct financial or beneficial interest; (2) notarizing the notary''s own signature; (3) notarizing a blank or incomplete document; (4) certifying any fact or statement as true when the notary has no personal knowledge of its truth; (5) engaging in the unauthorized practice of law, including giving legal advice, explaining the legal effect of a document, or recommending how a document should be completed; (6) charging fees in excess of the statutory maximum; (7) refusing to perform notarial services based on race, religion, national origin, or other protected characteristics while representing the notary as available. Each prohibited act carries specific liabilities and potential disciplinary action.', ARRAY['No notarizing with direct financial/beneficial interest', 'No notarizing own signature', 'No notarizing blank or incomplete documents', 'No certifying facts unknown to the notary', 'No unauthorized practice of law', 'No charging fees above statutory maximum', 'No discriminatory refusal of service'], 1, 'CA Government Code Sections 8224-8228, CA Secretary of State Notary Public Handbook (2025), Section 7', 'https://www.sos.ca.gov/notary'),

(7, 'Conflicts of Interest: Direct Financial or Beneficial Interest', 'A notary public is prohibited from notarizing any document in which the notary has a direct financial or beneficial interest. This means the notary cannot notarize a document that would directly result in a financial gain or advantage to the notary. For example, a notary who is a named beneficiary in a trust cannot notarize the trust document, and a notary who is a party to a contract cannot notarize signatures of other parties to that same contract. The interest must be "direct"—indirect or remote interests are not disqualifying. For instance, a notary who is a shareholder in a large publicly traded corporation generally may notarize documents for that corporation because the interest is not direct and personal. However, a notary who is an officer or director of a corporation should carefully consider whether a notarization for that corporation creates a conflict.', ARRAY['Cannot notarize with direct financial/beneficial interest', 'Named beneficiary in trust cannot notarize that trust', 'Party to a contract cannot notarize other parties', 'Interest must be "direct" to be disqualifying', 'Public company shareholder: generally not a conflict', 'Officers/directors should carefully assess conflicts'], 2, 'CA Government Code Section 8224, CA Secretary of State Notary Public Handbook (2025), Section 7', 'https://www.sos.ca.gov/notary'),

(7, 'Notarizing for Family Members', 'California law does not explicitly prohibit a notary from notarizing documents for family members, including spouses, children, parents, or siblings. However, the notary must carefully consider whether notarizing for a family member creates a direct financial or beneficial interest. The threshold question is whether the notary will receive a direct financial gain or benefit from the transaction being notarized. For example, a notary cannot notarize their spouse''s signature on a deed transferring property in which the notary has a community property interest. Even when no direct financial interest exists, the prudent practice is for notaries to avoid notarizing documents for close family members whenever possible, as it undermines the appearance of impartiality and increases the risk of challenges to the validity of the notarization.', ARRAY['Family notarization is not explicitly prohibited', 'Direct financial interest test still applies', 'Spouse deed with community property: prohibited', 'Prudent practice: avoid close family notarizations', 'Impartiality appearance may be undermined', 'Risk of validity challenges increases'], 3, 'CA Government Code Section 8224, CA Secretary of State Notary Public Handbook (2025), Section 7', 'https://www.sos.ca.gov/notary'),

(7, 'Never Notarize Blank or Incomplete Documents', 'A California notary must never notarize a document that contains blank spaces or is otherwise incomplete. While the notary is not responsible for the content of the document, notarizing a document with blank spaces creates a significant risk that someone could later fill in unauthorized information above the notarized signature, potentially committing fraud. If a document presented for notarization contains blanks (such as empty date fields, names of parties not filled in, dollar amounts left blank, or missing property descriptions), the notary must refuse to perform the notarization until all blanks are filled in. The notary may point to the blanks and suggest the signer complete them, but the notary must not fill in the blanks themselves. Once all blanks are filled, the notarization may proceed.', ARRAY['Never notarize documents with blank spaces', 'Blanks create risk of post-notarization fraud', 'Notary must refuse until all blanks are completed', 'Notary may point out blanks but cannot fill them in', 'Signer must complete all blanks', 'Once completed, notarization may proceed'], 4, 'CA Secretary of State Notary Public Handbook (2025), Section 7', 'https://www.sos.ca.gov/notary'),

(7, 'Unauthorized Practice of Law (UPL) and Immigration Consultant Restrictions', 'One of the most serious violations a notary can commit is engaging in the unauthorized practice of law (UPL). California notaries who are not licensed attorneys may not: give legal advice of any kind; recommend a specific document or suggest how a document should be completed; explain the legal effect, consequences, or meaning of a document; charge fees for legal services; or represent any person in a legal proceeding. Additionally, notaries who are not attorneys or qualified under federal regulations may not assist with immigration paperwork or hold themselves out as immigration consultants. The term "notario publico" creates a particular risk in Spanish-speaking communities, as in many Latin American countries a "notario publico" is a highly trained legal professional. California notaries must never use the term "notario publico" and must ensure that any advertising clearly states they are not attorneys.', ARRAY['Notaries cannot give legal advice', 'Cannot recommend or suggest documents', 'Cannot explain legal effect of documents', 'Cannot charge for legal services', 'Immigration consultant restrictions apply', 'Never use the term "notario publico"', 'Advertising must disclose notary is not an attorney'], 5, 'CA Government Code Sections 8223, 8228.1, CA Secretary of State Notary Public Handbook (2025), Section 7', 'https://www.sos.ca.gov/notary'),

(7, 'Surety Bond Liability', 'The $15,000 surety bond filed by every California notary serves a specific purpose: it provides a fund from which members of the public may recover damages if they suffer financial loss due to the notary''s misconduct or negligence. The bond is not insurance for the notary. If a claim is paid by the surety company, the notary is personally obligated to reimburse the surety company in full, including any attorneys'' fees or investigation costs. The bond covers the commission term and any renewal, but each claim is limited to the bond amount. The surety company may cancel the bond at any time by giving written notice to the county clerk and the Secretary of State, at which point the notary''s commission is suspended until a new bond is filed. A notary may also obtain errors and omissions insurance, which is a separate policy from the surety bond and covers the notary''s own defense costs and liability.', ARRAY['Surety bond protects the public, not the notary', 'Notary must reimburse surety for all claims paid', 'Reimbursement includes attorneys'' fees and costs', '$15,000 bond limit per claim', 'Bond cancellation suspends commission', 'Notary may separately obtain errors and omissions insurance'], 6, 'CA Government Code Sections 8212-8214, CA Secretary of State Notary Public Handbook (2025), Section 7', 'https://www.sos.ca.gov/notary'),

(7, 'Civil and Criminal Penalties for Notary Misconduct', 'A California notary who engages in misconduct may face both civil and criminal liability. Civil liability arises when a person suffers damages as a result of the notary''s negligent or wrongful notarial act. The injured party may sue the notary directly for damages and may also make a claim against the surety bond. Criminal liability may arise for serious violations: willful failure to perform the duties of a notary public is a misdemeanor, and certain fraudulent acts related to notarial duties may be prosecuted as felonies. Specifically, a notary who certifies that a document was signed, acknowledged, or sworn to by a person who did not personally appear before the notary may be subject to a civil penalty of up to $1,500 per violation, in addition to potential criminal prosecution. The Secretary of State may also revoke or suspend a notary''s commission for cause, including any violation of notary law.', ARRAY['Civil liability: injured party may sue for damages', 'Surety bond may be claimed for civil losses', 'Criminal liability: willful misconduct may be misdemeanor or felony', 'False certification of personal appearance: up to $1,500 penalty', 'Secretary of State can revoke or suspend commission', 'Multiple violations compound potential penalties'], 7, 'CA Secretary of State Notary Public Handbook (2025), Section 7', 'https://www.sos.ca.gov/notary');

-- ============================================
-- QUESTIONS: Chapter 1 (Introduction to Notaries) — 12 questions
-- ============================================

INSERT INTO questions (chapter_id, question, options, correct_index, explanation, source_ref) VALUES
(1, 'What is the most fundamental duty of a notary public?', ARRAY['To ensure all legal documents are enforceable', 'To serve as an impartial witness and deter fraud', 'To verify the legality of document contents', 'To provide authentication services for court filings'], 1, 'The most fundamental duty of a notary public is to serve as an impartial witness and deter fraud in the execution of documents. A notary does not ensure enforceability (that is for courts), verify legality of content (that is for attorneys and courts), or authenticate court filings (that is for court clerks). The notary''s role is to verify identity, confirm willingness, and maintain impartiality.', 'CA Secretary of State Notary Public Handbook (2025), Section 1'),

(1, 'A notary public is commissioned by which California agency or body?', ARRAY['The California Supreme Court', 'The county clerk in the notary''s county of residence', 'The California Secretary of State', 'The California Department of Consumer Affairs'], 2, 'The California Secretary of State commissions all notaries public in California. The county clerk''s role is to administer the oath and file the bond, but the county clerk does not issue the commission. The California Supreme Court and Department of Consumer Affairs have no role in the notary commissioning process.', 'CA Government Code Section 8200, CA Secretary of State Notary Public Handbook (2025), Section 1'),

(1, 'Which of the following is a California notary public NOT permitted to do?', ARRAY['Administer an oath or affirmation', 'Take an acknowledgment', 'Give legal advice about a document', 'Complete a notarial certificate'], 2, 'A notary public who is not also a licensed attorney is strictly prohibited from giving legal advice of any kind, including advice about the meaning, effect, or appropriateness of a document. Administering oaths, taking acknowledgments, and completing notarial certificates are all core duties that notaries are authorized to perform.', 'CA Government Code Section 8223, CA Secretary of State Notary Public Handbook (2025), Section 1'),

(1, 'The office of the notary public traces its historical origins to which civilization?', ARRAY['Ancient Greece', 'Ancient Rome', 'Medieval England', 'Colonial America'], 1, 'The notary public office originated in ancient Rome, where scribes known as "notarii" recorded legal proceedings and took shorthand notes. The practice later evolved through English common law and was brought to the American colonies.', 'CA Secretary of State Notary Public Handbook (2025), Section 1'),

(1, 'Which of the following is NOT one of the core functions of notarization?', ARRAY['Verifying the identity of the signer', 'Ensuring the signer is acting voluntarily', 'Creating an audit trail through the journal', 'Guaranteeing the legality of the document''s content'], 3, 'Notaries do not guarantee the legality of a document''s content. The core functions of notarization are identity verification, ensuring willingness and awareness, and creating a verifiable record (audit trail) through the journal. Determining or guaranteeing legality of content falls outside the notary''s role.', 'CA Secretary of State Notary Public Handbook (2025), Section 1'),

(1, 'What key characteristic distinguishes a notary public from a judge?', ARRAY['Notaries can administer oaths, but judges cannot', 'Judges adjudicate disputes; notaries cannot make legal rulings', 'Notaries are public servants; judges are private practitioners', 'Judges must be attorneys; all notaries are also attorneys'], 1, 'A judge adjudicates disputes and makes legal rulings. A notary cannot adjudicate disputes or make any legal rulings—their role is limited to witnessing signatures, administering oaths, and certifying copies. Notaries and judges both can administer oaths. Judges are public servants, not private practitioners. Not all notaries are attorneys (and most are not).', 'CA Secretary of State Notary Public Handbook (2025), Section 1'),

(1, 'A client enters a notary''s office and asks, "Which form should I use for this real estate deal? I have a grant deed and a quitclaim deed here." What should the notary do?', ARRAY['Explain the differences between the deed types and let the client choose', 'Recommend the quitclaim deed because it is commonly used', 'Tell the client the notary cannot recommend which form to use and suggest they consult a real estate professional or attorney', 'Complete whichever deed the client selects without comment'], 2, 'This is a request for legal advice. The notary must not recommend which form or document to use, as that constitutes the unauthorized practice of law. The notary should inform the client that they cannot make that recommendation and suggest the client consult a real estate professional, title company, or attorney.', 'CA Government Code Section 8223, CA Secretary of State Notary Public Handbook (2025), Section 1'),

(1, 'A notary public is required to maintain impartiality in all transactions. Which of the following actions would violate the duty of impartiality?', ARRAY['Refusing to notarize for a stranger who has no identification', 'Refusing to notarize for a person based on their national origin', 'Refusing to notarize a document with blank spaces', 'Refusing to notarize when the notary has a direct financial interest in the transaction'], 1, 'Refusing service based on a protected characteristic such as race, religion, nationality, or national origin violates the duty of impartiality and is unlawful discrimination. Refusing service due to lack of identification, blank documents, or conflicts of interest are all legitimate, lawful reasons to decline a notarization.', 'CA Government Code Section 8224, CA Secretary of State Notary Public Handbook (2025), Section 1'),

(1, 'What is the primary purpose of the notary''s journal?', ARRAY['To provide billing records for the notary''s services', 'To create a chronological audit trail of all notarial acts performed', 'To document the notary''s personal opinions about document signers', 'To serve as evidence of the notary''s attendance at the examination'], 1, 'The notary journal creates a chronological audit trail of all notarial acts performed, providing a permanent record that can be used as evidence in legal proceedings and to verify the details of any notarial act. It is not a billing document, opinion log, or examination attendance record.', 'CA Government Code Section 8206, CA Secretary of State Notary Public Handbook (2025), Section 1'),

(1, 'Which of the following best describes the relationship between a notary and the public?', ARRAY['The notary represents the interests of the party paying the notary fee', 'The notary serves as a public officer who owes a duty to the transaction as a whole', 'The notary acts as an agent for the document preparer', 'The notary serves as a representative of the county clerk''s office'], 1, 'A notary is a public officer who owes a duty of impartiality to the entire transaction, not to any individual party. The notary does not represent the person paying the fee, the document preparer, or the county clerk. The notary''s duty is to the integrity of the transaction itself.', 'CA Secretary of State Notary Public Handbook (2025), Section 1'),

(1, 'A document signer tells the notary, "I don''t really understand this document, but I need to sign it anyway." What is the most appropriate response?', ARRAY['Notarize the document since the signer appears willing', 'Explain the document to the signer to help them understand it', 'Ask the signer if they are being coerced and suggest they seek legal advice before signing', 'Tell the signer to sign the document without reading it since the notary cannot explain it anyway'], 2, 'If a signer expresses confusion about a document, the notary should be alert to potential coercion or lack of willingness. The notary should ask if the signer feels pressured and suggest they seek legal advice before proceeding. The notary cannot explain the document (that would be UPL) but should also not notarize if there are signs the signer is not acting voluntarily or knowingly.', 'CA Secretary of State Notary Public Handbook (2025), Section 1'),

(1, 'What happens if a notary commission expires and the notary performs a notarial act after the expiration date?', ARRAY['The notarial act remains valid as long as the notary renews the commission within 30 days', 'The notarial act is void because the notary had no legal authority to act at that time', 'The notarial act is valid but the notary must pay a late renewal fee', 'The notarial act is valid only if the signer was aware of the expired commission'], 1, 'Once a notary''s commission expires, the notary has no legal authority to perform any notarial act. Any act performed after expiration is void. There is no grace period, late renewal forgiveness, or exception based on signer knowledge. The notary must complete the full reappointment process before performing any notarial acts again.', 'CA Secretary of State Notary Public Handbook (2025), Sections 1-2');

-- ============================================
-- QUESTIONS: Chapter 2 (Appointment and Qualifications) — 12 questions
-- ============================================

INSERT INTO questions (chapter_id, question, options, correct_index, explanation, source_ref) VALUES
(2, 'What is the minimum age to become a notary public in California?', ARRAY['16 years old', '21 years old', '18 years old', '25 years old'], 2, 'California law requires a notary public applicant to be at least 18 years of age. There is no maximum age limit.', 'CA Government Code Section 8201, CA Secretary of State Notary Public Handbook (2025), Section 2'),

(2, 'A lawful permanent resident (green card holder) of California who is not a U.S. citizen applies for a notary commission. What is the outcome?', ARRAY['The application is denied because citizenship is required', 'The application is accepted because California law does not require U.S. citizenship', 'The application is held pending the applicant obtaining citizenship', 'The application is accepted but limited to a two-year term'], 1, 'California law does not require U.S. citizenship for a notary public commission. Lawful permanent residents (green card holders) and other legal residents of California are eligible, provided they meet all other statutory requirements.', 'CA Government Code Section 8201, CA Secretary of State Notary Public Handbook (2025), Section 2'),

(2, 'The six-hour course of study for new notary applicants must be completed within what time period before the examination?', ARRAY['One year', 'Three months', 'Thirty days', 'Six months'], 3, 'The six-hour course of study must be completed within six months before the date of the notary public examination. The certificate of completion must be presented at the exam site. A course completed more than six months before the exam is not valid.', 'CA Government Code Section 8201.1, CA Secretary of State Notary Public Handbook (2025), Section 2'),

(2, 'What is the purpose of the Live Scan fingerprinting requirement for notary applicants?', ARRAY['To register the applicant in the state identification database', 'To conduct a criminal background check through the California DOJ and FBI', 'To verify the applicant''s employment history', 'To create a biometric record for the notary journal'], 1, 'Live Scan fingerprinting is used to conduct a criminal background check through the California Department of Justice (DOJ) and the Federal Bureau of Investigation (FBI). This allows the Secretary of State to determine whether the applicant meets the character and fitness requirements for commission.', 'CA Government Code Section 8201.5, CA Secretary of State Notary Public Handbook (2025), Section 2'),

(2, 'A notary applicant taking the examination for the first time arrives at the test center but realizes they forgot their course completion certificate. What should they expect?', ARRAY['They can take the exam and submit the certificate later', 'They can take the exam but will receive a provisional score', 'They will be denied admission to the examination', 'They can take the exam but must pay an additional fee'], 2, 'Without a valid course completion certificate presented at the exam site, the applicant will be denied admission to the examination. There is no provision for taking the exam and submitting the certificate later, receiving a provisional score, or paying an additional fee to bypass this requirement.', 'CA Secretary of State Notary Public Handbook (2025), Section 2'),

(2, 'What is the required surety bond amount for a California notary public?', ARRAY['$5,000', '$10,000', '$15,000', '$25,000'], 2, 'California law requires every notary public to file a $15,000 surety bond with the county clerk. The bond amount has been $15,000 since the statutory update to Government Code Section 8212.', 'CA Government Code Section 8212, CA Secretary of State Notary Public Handbook (2025), Section 2'),

(2, 'What happens if a notary''s surety bond is cancelled during the commission term?', ARRAY['The commission continues and the notary has 60 days to replace the bond', 'The commission is automatically suspended until a new bond is filed', 'The commission is permanently revoked with no opportunity for reinstatement', 'The commission continues but the notary is personally liable for all acts'], 1, 'If the surety bond is cancelled or lapses, the notary''s commission is automatically suspended. The notary must file a new bond with the county clerk to have the commission reinstated. The commission is not permanently revoked, and the notary cannot legally perform notarial acts during the suspension period.', 'CA Government Code Section 8213, CA Secretary of State Notary Public Handbook (2025), Section 2'),

(2, 'After passing the examination and receiving a commission, a California notary must file the oath and bond with the county clerk within how many days?', ARRAY['15 calendar days', '30 calendar days', '60 calendar days', '90 calendar days'], 1, 'The notary must file the oath of office and surety bond with the county clerk within 30 calendar days of the commission''s start date. Failure to file within this period voids the commission, and the applicant must restart the entire process from the beginning.', 'CA Government Code Sections 8203-8204, CA Secretary of State Notary Public Handbook (2025), Section 2'),

(2, 'A notary who is renewing their commission must complete which type of course?', ARRAY['The full six-hour course, regardless of experience', 'A three-hour refresher course', 'No course is required for renewal', 'A one-hour online update course'], 1, 'A notary applying for reappointment (renewal) must complete a three-hour refresher course. However, if the previous commission has already expired before the notary takes the examination for reappointment, the full six-hour course is required instead.', 'CA Government Code Section 8201.1, CA Secretary of State Notary Public Handbook (2025), Section 2'),

(2, 'A California notary relocates from Los Angeles County to San Francisco County midway through the commission term. What is required?', ARRAY['The notary must re-take the oath and bond in San Francisco County', 'The notary must notify the Secretary of State of the address change within 30 days', 'The notary''s commission becomes void and a new application is required', 'The notary can continue without any notification since the commission is statewide'], 1, 'A notary who changes their address must notify the Secretary of State within 30 days. The commission remains valid statewide regardless of which county the notary resides in. There is no need to re-take the oath, re-file the bond in the new county, or obtain a new commission.', 'CA Secretary of State Notary Public Handbook (2025), Section 2'),

(2, 'Which of the following would most likely disqualify an applicant from receiving a notary commission?', ARRAY['The applicant has a traffic ticket from three years ago', 'The applicant has been convicted of a felony and has not had civil rights restored', 'The applicant is a full-time student', 'The applicant was previously self-employed'], 1, 'A felony conviction is disqualifying unless the applicant''s civil and firearm rights have been fully restored in the jurisdiction of conviction. Traffic tickets, student status, and self-employment history have no bearing on notary commission eligibility.', 'CA Government Code Section 8201, CA Secretary of State Notary Public Handbook (2025), Section 2'),

(2, 'Which statement about the California notary commission term is correct?', ARRAY['The commission term is two years and automatically renews', 'The commission term is four years and requires re-examination for reappointment', 'The commission term is five years and can be renewed by paying a fee', 'The commission term is lifetime unless revoked for cause'], 1, 'The California notary commission term is four years. There is no automatic renewal, no simple fee-based renewal, and no lifetime commission. Reappointment requires completing a refresher course, passing the examination again, submitting new fingerprints, and filing a new bond.', 'CA Government Code Section 8202, CA Secretary of State Notary Public Handbook (2025), Section 2');

-- ============================================
-- QUESTIONS: Chapter 3 (Jurisdiction and Geographic Authority) — 12 questions
-- ============================================

INSERT INTO questions (chapter_id, question, options, correct_index, explanation, source_ref) VALUES
(3, 'Where does a California notary public have authority to perform notarial acts?', ARRAY['Only in the county where the notary filed their oath and bond', 'Anywhere in California, plus in bordering states if the document is for California use', 'Anywhere within the geographic boundaries of the State of California', 'In any state as long as the notary uses a California notary seal'], 2, 'A California notary has statewide jurisdiction—they may perform notarial acts anywhere within the geographic boundaries of California. Their authority does not extend to any other state under any circumstances. The commission is valid throughout all 58 counties, not just the county where the oath and bond were filed.', 'CA Government Code Section 8225, CA Secretary of State Notary Public Handbook (2025), Section 3'),

(3, 'A California notary is on vacation in Las Vegas, Nevada. A friend asks them to notarize a document while they are there. What should the notary do?', ARRAY['Notarize the document since they are a commissioned California notary', 'Notarize the document but only if it will be filed in California', 'Decline because the notary is physically outside California and has no authority to act in Nevada', 'Notarize the document if the signer is also a California resident'], 2, 'A California notary has no authority whatsoever to perform notarial acts outside the state of California. The notary''s physical location at the time of the act determines jurisdiction. Being on vacation in Nevada means the notary cannot perform any notarial acts there, regardless of where the document will be filed or where the signer resides.', 'CA Secretary of State Notary Public Handbook (2025), Section 3'),

(3, 'A document notarized by a California notary within California is intended for use in New York. Under what principle would New York generally recognize this notarization?', ARRAY['The principle of exclusive state jurisdiction', 'The Full Faith and Credit Clause and principles of comity', 'The Uniform Notary Recognition Act', 'New York would not recognize the California notarization at all'], 1, 'Under the Full Faith and Credit Clause of the U.S. Constitution and principles of comity between states, a notarization properly performed by a California notary within California is generally recognized as valid by other states, including New York. States do, however, have their own specific requirements that should be considered.', 'CA Secretary of State Notary Public Handbook (2025), Section 3'),

(3, 'A California notary is asked to notarize a New York real estate contract. The signer is physically present in the notary''s California office. What should the notary do?', ARRAY['Refuse because the document is from another state', 'Notarize the document using California certificate wording, since both parties are in California', 'Use the New York certificate form for the notarization', 'Contact the New York Secretary of State for permission before proceeding'], 1, 'A California notary may notarize a document from another state as long as the notary and signer are both physically present in California at the time of the notarization. The notary should use California certificate wording—not an out-of-state form that may conflict with California law. The notary does not need permission from the other state to proceed.', 'CA Secretary of State Notary Public Handbook (2025), Section 3'),

(3, 'What determines which jurisdiction''s notary law applies to a notarial act?', ARRAY['The state where the document was prepared', 'The state where the document will be filed', 'The state where the notary is physically located at the time of the act', 'The state where the signer resides'], 2, 'The notarial act is governed by the law of the jurisdiction where the notary is physically located when performing the act. This is a fundamental principle: the location of the notary (not the document''s origin, destination, or the signer''s residence) determines applicable law.', 'CA Secretary of State Notary Public Handbook (2025), Section 3'),

(3, 'A notary commissioned in Arizona performs a notarization for a California resident in Arizona. Will California recognize this notarization?', ARRAY['No, because the notary is not commissioned in California', 'Yes, generally, because the act was performed in Arizona where the notary had authority', 'Only if the document will be filed in Arizona', 'Only if the Arizona notary also holds a California commission'], 1, 'California generally recognizes notarial acts performed by out-of-state notaries, provided the acts were performed in the notary''s home state where the notary had authority. The document does not need a California notary, and the notary does not need a California commission.', 'CA Secretary of State Notary Public Handbook (2025), Section 3'),

(3, 'Which of the following statements about electronic notarization in California is correct?', ARRAY['Electronic notarization in California does not require the signer and notary to be in the same room', 'Electronic notarization in California still requires the signer and notary to be physically present in the same location', 'Electronic notarization is not permitted in California under any circumstances', 'Electronic notarization requires the signer to have a California driver''s license'], 1, 'Electronic notarization—in which the notary uses an electronic signature and electronic seal to notarize an electronic document—still requires the notary and signer to be physically present in the same room. Electronic notarization is different from remote online notarization, which allows the signer to appear via audio-visual technology.', 'CA Secretary of State Notary Public Handbook (2025), Section 3'),

(3, 'A California notary relocates their principal place of business from Orange County to Riverside County. Which statement is correct?', ARRAY['The commission is automatically voided', 'The notary must re-file the oath and bond in Riverside County', 'The commission remains valid statewide; only an address update is required', 'The notary can only act in Riverside County after the move'], 2, 'The California notary commission is valid statewide. When relocating to a different county within California, the notary''s commission remains fully valid. The notary does not need to re-file the oath and bond in the new county. However, the notary must notify the Secretary of State of the address change within 30 days.', 'CA Secretary of State Notary Public Handbook (2025), Section 3'),

(3, 'Remote online notarization (RON) in California requires which of the following?', ARRAY['The signer and notary must be in the same city', 'The notary must use a technology platform meeting statutory requirements, with identity proofing and audio-visual recording', 'The signer must be a California resident', 'The document must be filed in California'], 1, 'California remote online notarization (RON) requires the use of a technology platform meeting statutory requirements that provides identity proofing (credential analysis and knowledge-based authentication) and audio-visual recording capabilities. The signer does not need to be a California resident, and the document does not need to be filed in California.', 'CA Secretary of State Notary Public Handbook (2025), Section 3'),

(3, 'Which body regulates and oversees notaries public in California?', ARRAY['The California State Bar', 'The California Department of Justice', 'The California Secretary of State', 'The county clerk in each county'], 2, 'The California Secretary of State is the regulatory body that commissions, oversees, and may revoke or suspend notaries public in California. The California State Bar regulates attorneys, not notaries. The Department of Justice processes background checks but does not regulate notaries. County clerks file oaths and bonds but do not regulate notaries.', 'CA Government Code Section 8200, CA Secretary of State Notary Public Handbook (2025), Section 3'),

(3, 'A document notarized in California is intended for use in a foreign country. What additional step may be required?', ARRAY['The notary must obtain a special international commission', 'The document may need an apostille or authentication certificate from the California Secretary of State', 'The notary must send the document to the U.S. Department of State for approval', 'Foreign countries cannot accept California notarizations under any circumstances'], 1, 'For a document to be used in a foreign country, it may need an apostille (for countries that are parties to the Hague Convention) or an authentication certificate (for other countries) from the California Secretary of State. The Secretary of State verifies that the notary was in good standing at the time of the notarization. This is separate from the notarization itself.', 'CA Secretary of State Notary Public Handbook (2025), Section 3'),

(3, 'If a California notary is uncertain about whether a document being prepared for another state should use a California or out-of-state certificate, what is the safest approach?', ARRAY['Use the out-of-state certificate to satisfy the other state', 'Use both certificates attached to the document', 'Use the California certificate and let the receiving state determine acceptability', 'Refuse to notarize the document entirely'], 2, 'When in doubt, the safest approach is to use the California notarial certificate, since the notary is performing the act under California law. The receiving state will determine whether the California certificate meets its requirements. Using an out-of-state form that conflicts with California law could create liability for the notary. Refusing to notarize is an option but is unnecessarily restrictive in most cases.', 'CA Secretary of State Notary Public Handbook (2025), Section 3');

-- ============================================
-- QUESTIONS: Chapter 4 (Types of Notarial Acts) — 14 questions
-- ============================================

INSERT INTO questions (chapter_id, question, options, correct_index, explanation, source_ref) VALUES
(4, 'In an acknowledgment, must the signer sign the document in the notary''s presence?', ARRAY['Yes, the signature must be made in the notary''s immediate presence', 'No, the signer may have signed the document before appearing before the notary', 'Yes, but only for documents involving real property', 'No, but the notary must call the signer by phone to confirm the signature'], 1, 'In an acknowledgment, the signer does not need to sign the document in the notary''s presence. The signer simply appears before the notary and acknowledges that the existing signature on the document is their own and was made voluntarily. This distinguishes an acknowledgment from a jurat, where the signer must sign (or re-sign) in the notary''s presence.', 'CA Government Code Section 1185, CA Secretary of State Notary Public Handbook (2025), Section 4'),

(4, 'Which notarial act requires the notary to administer an oath or affirmation?', ARRAY['Acknowledgment', 'Certified copy of power of attorney', 'Jurat', 'Signature witnessing'], 2, 'A jurat requires the notary to administer an oath or affirmation to the signer, who must swear or affirm under penalty of perjury that the contents of the document are true and correct. Acknowledgments and certified copies do not require an oath. Signature witnessing involves watching the signing but does not include an oath.', 'CA Government Code Section 8202, CA Secretary of State Notary Public Handbook (2025), Section 4'),

(4, 'A signer appears with a document that was already signed two days ago. The signer needs the notary to verify that the signature is theirs. Which notarial act is appropriate?', ARRAY['Jurat', 'Oath or affirmation', 'Acknowledgment', 'Certified copy'], 2, 'An acknowledgment is the appropriate notarial act when the signer has already signed the document and needs to confirm that the signature is their own. The signer does not need to re-sign. A jurat would require the signer to re-sign in the notary''s presence and take an oath, which is not necessary when the signer is merely confirming a pre-existing signature.', 'CA Secretary of State Notary Public Handbook (2025), Section 4'),

(4, 'A signer brings an unsigned affidavit to the notary and asks the notary to notarize it. The signer intends to sign the document in the notary''s presence and swear to the truth of its contents. Which act should the notary perform?', ARRAY['Acknowledgment', 'Jurat', 'Certified copy', 'Signature witnessing only, no oath required'], 1, 'A jurat is required when the signer must sign the document in the notary''s presence and swear or affirm to the truthfulness of the contents under penalty of perjury. Affidavits typically require a jurat. An acknowledgment alone would not be sufficient because the oath component is missing.', 'CA Secretary of State Notary Public Handbook (2025), Section 4'),

(4, 'What is the fundamental difference between an oath and an affirmation?', ARRAY['An oath is legally binding; an affirmation is not', 'An oath invokes a deity; an affirmation is a non-religious pledge of truthfulness', 'An oath is for criminal proceedings; an affirmation is for civil proceedings', 'There is no difference—the terms are interchangeable'], 1, 'An oath invokes a supreme being or deity as a witness to the truth of a statement ("I swear by Almighty God that..."). An affirmation is an equivalent declaration that does not invoke a deity ("I solemnly affirm that..."), used by individuals who object to religious oaths for personal or religious reasons. Both carry the same legal weight under California law.', 'CA Secretary of State Notary Public Handbook (2025), Section 4'),

(4, 'Under California law, a notary public is authorized to certify copies of which type of document?', ARRAY['Birth certificates', 'Court judgments', 'A power of attorney', 'School transcripts'], 2, 'Under California law, a notary public is only authorized to certify copies of a power of attorney. A notary may not certify copies of birth certificates, death certificates, marriage licenses, court records, school transcripts, or any other documents. A separate notarial certificate exists specifically for this purpose.', 'CA Government Code Section 8205, CA Secretary of State Notary Public Handbook (2025), Section 4'),

(4, 'A signer presents a birth certificate and asks the notary to make a certified copy. What should the notary do?', ARRAY['Make the certified copy since it is a standard notarial function', 'Make the certified copy but use the general certificate form', 'Decline and explain that California notaries cannot certify copies of birth certificates', 'Send the signer to a different notary who may have the certification authority'], 2, 'A California notary public is not authorized to certify copies of birth certificates. The notary should decline and explain this limitation. Only a power of attorney may be certified by a California notary. Referring the signer elsewhere is not appropriate because the limitation applies to all California notaries.', 'CA Government Code Section 8205, CA Secretary of State Notary Public Handbook (2025), Section 4'),

(4, 'A signer appears and wants a notarization but does not know which type of act is needed. What is the notary''s proper course of action?', ARRAY['Choose a jurat since it includes the oath and is therefore more comprehensive', 'Choose an acknowledgment since it is the most commonly used form', 'Ask the signer to determine which act is needed, or suggest they ask the document preparer or an attorney', 'Complete both an acknowledgment and a jurat to be safe'], 2, 'The notary must never choose which notarial act to perform. The choice between an acknowledgment and a jurat has different legal consequences, and selecting the wrong one can affect the validity of the document. The signer must tell the notary which act is required. If the signer does not know, the notary should suggest the signer ask the document preparer, the receiving party, or an attorney.', 'CA Secretary of State Notary Public Handbook (2025), Section 4'),

(4, 'For a jurat, the signer must do which of the following?', ARRAY['Only acknowledge that they previously signed the document', 'Provide two forms of identification', 'Sign the document in the notary''s presence and swear or affirm to its truth', 'Read the entire document aloud in the notary''s presence'], 2, 'For a jurat, the signer must (1) sign the document in the notary''s presence (or re-sign if already signed) and (2) swear or affirm under penalty of perjury that the contents of the document are true and correct. The notary must administer the oath or affirmation. The signer does not need to read the document aloud, and two forms of ID are not required (one satisfactory ID or personal knowledge is sufficient).', 'CA Government Code Section 8202, CA Secretary of State Notary Public Handbook (2025), Section 4'),

(4, 'What is a notarial protest?', ARRAY['A formal objection filed by a notary against improper government action', 'A formal certificate attesting that a negotiable instrument was presented and refused', 'A sworn statement by a notary reporting misconduct to the Secretary of State', 'A declaration by a signer challenging the validity of a notarization'], 1, 'A protest is a formal notarial certificate attesting that a negotiable instrument (such as a check, promissory note, or bill of exchange) was presented for payment or acceptance and was refused. It is governed by the Uniform Commercial Code and is primarily used in commercial and banking transactions involving dishonored instruments.', 'CA Secretary of State Notary Public Handbook (2025), Section 4'),

(4, 'Which notarial act involves signature witnessing but does NOT include an oath or affirmation?', ARRAY['Jurat', 'Acknowledgment', 'Signature witnessing (as a distinct act)', 'Oath administration'], 2, 'Signature witnessing, as a distinct notarial act, involves the signer signing the document in the notary''s presence while the notary verifies the signer''s identity and witnesses the signing. Unlike a jurat, no oath or affirmation is administered. Unlike an acknowledgment, the signature must be made in the notary''s presence.', 'CA Secretary of State Notary Public Handbook (2025), Section 4'),

(4, 'A document signer appears and says, "I need you to swear me in for this affidavit." The signer then signs the document and raises their right hand. The notary asks, "Do you swear under penalty of perjury that the statements in this document are true and correct?" The signer answers "Yes." Which notarial act has been performed?', ARRAY['Acknowledgment', 'Jurat', 'Signature witnessing', 'Certified copy'], 1, 'This describes a jurat. The key elements are all present: (1) the signer signed in the notary''s presence, (2) the signer raised their right hand (appropriate gesture for an oath), and (3) the notary administered an oath, asking the signer to swear to the truth of the document''s contents under penalty of perjury. An acknowledgment would not involve signing in the notary''s presence or taking an oath.', 'CA Secretary of State Notary Public Handbook (2025), Section 4'),

(4, 'A notary completes a certificate of acknowledgment. Which of the following must be included in the certificate?', ARRAY['The signer''s thumbprint', 'The venue (state and county), date, signer name, and notary signature with seal', 'The signer''s social security number', 'A statement that the notary has read the document'], 1, 'A certificate of acknowledgment must include the venue (state and county where the act took place), the date of the notarial act, the name of the person appearing before the notary, and the notary''s signature and seal. The thumbprint is required in the journal (not the certificate) for deeds. The signer''s SSN is never required. The notary does not read the document.', 'CA Government Code Section 1189, CA Secretary of State Notary Public Handbook (2025), Section 4'),

(4, 'Which of the following correctly pairs a notarial act with its defining feature?', ARRAY['Acknowledgment — requires an oath', 'Jurat — the signer may sign before appearing', 'Oath/Affirmation — may be performed as an independent notarial act', 'Certified copy — available for any type of document'], 2, 'An oath or affirmation may be performed as an independent notarial act, separate from a jurat. An acknowledgment does not require an oath. A jurat requires signing in the notary''s presence (the signer cannot sign beforehand). A certified copy is only available for powers of attorney under California law.', 'CA Secretary of State Notary Public Handbook (2025), Section 4');

-- ============================================
-- QUESTIONS: Chapter 5 (Identifying Document Signers) — 12 questions
-- ============================================

INSERT INTO questions (chapter_id, question, options, correct_index, explanation, source_ref) VALUES
(5, 'Which of the following is considered "satisfactory evidence" of identity under California notary law?', ARRAY['A social security card', 'A valid California driver''s license', 'A credit card with the signer''s name', 'A library card with a photograph'], 1, 'A valid California driver''s license meets the statutory requirements: it is a government-issued document containing a photograph, physical description, signature, and serial number. A social security card has no photograph. A credit card is not government-issued. A library card, even with a photograph, is not a government-issued identification document.', 'CA Government Code Section 1185, CA Secretary of State Notary Public Handbook (2025), Section 5'),

(5, 'A notary identifies a signer based on "personal knowledge." What does this mean?', ARRAY['The notary looked up the signer on social media', 'The notary has firsthand familiarity with the person through regular dealings, with no reasonable doubt about their identity', 'The notary recognized the signer''s name from a previous transaction', 'The notary accepted a verbal introduction from a mutual acquaintance'], 1, 'Personal knowledge means the notary has direct, firsthand familiarity with the individual, derived from association in the course of regular dealings, such that no reasonable doubt exists about the person''s identity. A social media lookup, name recognition, or a verbal introduction from a third party does not constitute personal knowledge.', 'CA Government Code Section 1185, CA Secretary of State Notary Public Handbook (2025), Section 5'),

(5, 'A signer presents a U.S. passport that expired two years ago as identification. Is this acceptable?', ARRAY['No, all expired identification documents are invalid', 'Yes, because a passport is always valid for identification purposes', 'Yes, if the passport is otherwise unaltered, because it was issued within the past five years', 'Only if the signer also provides a second form of identification'], 2, 'Under California law, an identification document may be recently expired if it was issued within the past five years. A passport that expired two years ago was likely issued within that window. The notary must still verify that the photograph and physical description match the signer. The five-year window applies to all qualifying forms of government-issued ID, not just passports.', 'CA Secretary of State Notary Public Handbook (2025), Section 5'),

(5, 'A signer presents a valid California driver''s license, but the notary notices that the photograph of the person on the license does not reasonably match the person standing before them. What should the notary do?', ARRAY['Accept the ID anyway since it is government-issued and unexpired', 'Ask the signer if they have recently changed their appearance', 'Refuse to proceed based on that identification and request another form of acceptable ID', 'Call the police to report suspected fraud immediately'], 2, 'If the photograph on an identification document does not reasonably match the signer''s appearance, the notary must consider the ID insufficient and refuse to proceed based on that identification. The notary should offer the signer the option of providing another acceptable ID or using the credible witness procedure. The notary is not required to call the police unless they have specific evidence of attempted fraud.', 'CA Secretary of State Notary Public Handbook (2025), Section 5'),

(5, 'Under the credible witness procedure, how many credible witnesses are required if no witness is personally known to the notary?', ARRAY['One credible witness with valid identification', 'Two credible witnesses, each with valid identification', 'Three credible witnesses', 'One credible witness, no identification required'], 1, 'When using the credible witness procedure and no credible witness is personally known to the notary, two credible witnesses are required. Each must be identified by the notary (through personal knowledge or satisfactory evidence), and each must swear under oath as to the signer''s identity. If one credible witness is personally known to the notary, only that one witness is required.', 'CA Government Code Section 1185, CA Secretary of State Notary Public Handbook (2025), Section 5'),

(5, 'Which of the following identification documents would be considered insufficient for notarial purposes?', ARRAY['A current U.S. military identification card', 'A California identification card issued by the DMV', 'A social security card', 'A foreign passport stamped by U.S. immigration authorities'], 2, 'A social security card lacks a photograph, physical description, and signature visible on the card itself, making it insufficient for identification under California notary law. All three other options are types of government-issued identification that meet statutory requirements.', 'CA Secretary of State Notary Public Handbook (2025), Section 5'),

(5, 'A notary suspects an identification document may be fraudulent. The signer is cooperative but insistent. What is the notary''s best course of action?', ARRAY['Notarize the document but note the suspicion in the journal', 'Refuse the notarization and document the refusal with the reason in the journal', 'Confiscate the suspected fraudulent ID and call law enforcement', 'Proceed with the notarization but use the credible witness procedure instead'], 1, 'If a notary suspects an ID is fraudulent, they must refuse to proceed with the notarization based on that ID. The notary should document the refusal in their journal, noting the reason. The notary may also offer the credible witness procedure as an alternative, but should not proceed based on the suspected-fraudulent ID. Notaries generally do not have the authority or obligation to confiscate suspected fraudulent IDs.', 'CA Secretary of State Notary Public Handbook (2025), Section 5'),

(5, 'What must a California notary record in their journal about the identification used?', ARRAY['Only the type of ID (e.g., "driver''s license")', 'The type of ID, issuing agency, serial/identifying number, and issue and expiration dates', 'A photocopy of the identification document', 'Just the signer''s date of birth'], 1, 'California law requires the notary to record in the journal the type of identification used, the issuing agency, the serial or identifying number, and the issue and expiration dates of the identification document. A photocopy is not required by statute. The name and date of birth are part of the signer''s personal information recorded in the journal separately from the ID details.', 'CA Government Code Section 8206, CA Secretary of State Notary Public Handbook (2025), Section 5'),

(5, 'In remote online notarization (RON), which of the following methods is used to verify a signer''s identity?', ARRAY['The signer simply shows their ID to the camera', 'The notary visits the signer''s home to verify identity', 'The technology platform performs credential analysis and knowledge-based authentication (KBA)', 'The signer''s employer vouches for their identity via email'], 2, 'California remote online notarization requires the use of a technology platform that performs multi-step identity proofing, including credential analysis (technology-based verification of the ID''s authenticity) and knowledge-based authentication (KBA, which asks personal questions derived from data sources). Simply showing an ID on camera is insufficient. In-person visits and employer vouching are not statutory methods for RON.', 'CA Secretary of State Notary Public Handbook (2025), Section 5'),

(5, 'A notary knows the signer through weekly interactions at a community volunteer program over the past two years. The signer forgot their ID. Can the notary proceed based on personal knowledge?', ARRAY['No, ID is always required regardless of personal knowledge', 'Yes, if the notary has sufficient firsthand familiarity through regular dealings and has no reasonable doubt about the identity', 'Only if the notary has known the signer for at least five years', 'Only if the signer provides an additional non-government ID'], 1, 'If the notary has firsthand familiarity with the individual through regular dealings and has no reasonable doubt about the signer''s identity, personal knowledge can serve as sufficient identification. There is no five-year minimum, and no additional non-government ID is required. Regular interaction through a volunteer program over two years could satisfy this standard if the notary has no doubt.', 'CA Government Code Section 1185, CA Secretary of State Notary Public Handbook (2025), Section 5'),

(5, 'What is the risk to a notary who relies solely on a credit card for identification?', ARRAY['There is no risk—credit cards are widely accepted forms of identification', 'The notary has violated the law because a credit card does not meet the statutory requirements for satisfactory evidence', 'The notary is only at risk if the credit card is expired', 'The notary needs only to verify the signature matches'], 1, 'A credit card does not meet the statutory requirements for satisfactory evidence of identity—it lacks a photograph and physical description and is not issued by a government agency. Relying on a credit card alone constitutes a violation of California notary law and exposes the notary to civil and criminal liability, regardless of whether the credit card is current or the signature matches.', 'CA Government Code Section 1185, CA Secretary of State Notary Public Handbook (2025), Section 5'),

(5, 'When a notary uses the credible witness procedure, what oath must the credible witness take?', ARRAY['An oath that the witness has known the notary for at least ten years', 'An oath swearing to the identity of the document signer', 'An oath that the witness has read and understood the document being notarized', 'An oath of loyalty to the State of California'], 1, 'Each credible witness must swear under oath that the document signer is the person they claim to be. The oath relates to the signer''s identity, not the witness''s relationship with the notary, the content of the document, or any other matter. The notary administers this oath, and each witness must be identified by the notary.', 'CA Government Code Section 1185, CA Secretary of State Notary Public Handbook (2025), Section 5');

-- ============================================
-- QUESTIONS: Chapter 6 (Record Keeping and Notary Journals) — 12 questions
-- ============================================

INSERT INTO questions (chapter_id, question, options, correct_index, explanation, source_ref) VALUES
(6, 'Is a sequential journal mandatory for California notaries public?', ARRAY['No, a journal is optional but recommended', 'Yes, a sequential journal is required by law for all notarial acts', 'Only if the notary performs more than 10 notarizations per month', 'Only for notarizations involving real property'], 1, 'California law requires every notary public to keep a sequential journal of all notarial acts performed. There are no exceptions for low-volume notaries or for any type of notarial act. The journal requirement applies to every notarial act, not just those involving real property.', 'CA Government Code Section 8206, CA Secretary of State Notary Public Handbook (2025), Section 6'),

(6, 'When must a California notary receive a right thumbprint from a signer?', ARRAY['For every notarial act the notary performs', 'For any document that the notary considers important', 'When the document is a deed, quitclaim deed, or deed of trust affecting real property', 'Only when the signer is not personally known to the notary'], 2, 'The right thumbprint is required by statute when the document being notarized is a deed, quitclaim deed, or deed of trust affecting real property. It is not required for every notarial act, for documents the notary deems important, or based on the signer''s relationship to the notary. The thumbprint is recorded in the journal.', 'CA Government Code Section 8206, CA Secretary of State Notary Public Handbook (2025), Section 6'),

(6, 'A notary realizes they made an error in a journal entry after the signer has left. What is the proper way to correct it?', ARRAY['Use white-out to cover the error and write the correction', 'Erase the error and write the correct information', 'Draw a single line through the error, write the correction nearby, and initial and date the change', 'Tear out the page and start a new entry on the next page'], 2, 'The correct procedure is to draw a single line through the erroneous information so that it remains legible, write the correct information in a nearby space or margin, and initial the correction. If discovered later (after the signer has left), the notary should also note the date the correction was made. White-out, erasing, or tearing out pages is strictly prohibited and may be considered evidence of an attempt to conceal misconduct.', 'CA Secretary of State Notary Public Handbook (2025), Section 6'),

(6, 'Who has the right to possess and control a notary''s journal?', ARRAY['The notary''s employer, since they provided the workspace', 'The notary, who must keep the journal in their exclusive custody and control', 'The county clerk, who receives it upon the notary''s retirement only', 'The Secretary of State, upon written request'], 1, 'The notary journal is the property of the notary and must be kept in the notary''s exclusive custody and control at all times. Even if the notary''s employer purchased the journal or the notary performs notarizations at the employer''s workplace, the employer has no right to possess or control the journal. The journal is surrendered to the county clerk only upon end of commission.', 'CA Government Code Section 8206, CA Secretary of State Notary Public Handbook (2025), Section 6'),

(6, 'After a notary''s commission expires without renewal, what must happen to the notary''s journals?', ARRAY['The journals should be destroyed to protect signer privacy', 'The journals continue to be retained by the notary for life', 'The journals must be delivered to the county clerk within 30 days', 'The journals are automatically transferred to the Secretary of State'], 2, 'When a notary''s commission expires without renewal, or if the notary resigns, the journals must be delivered to the county clerk in the county where the notary''s oath and bond were filed, within 30 days. The journals should never be destroyed. The county clerk retains them according to local records retention schedules.', 'CA Government Code Section 8206, CA Secretary of State Notary Public Handbook (2025), Section 6'),

(6, 'Which of the following is required to be recorded in each journal entry?', ARRAY['The signer''s social security number', 'The signer''s occupation and employer', 'The date, time, type of notarial act, and description of the document', 'The signer''s immigration status'], 2, 'Each journal entry must include the date and time of the notarial act, the type of notarial act, the type and title or description of the document, and the document date. The signer''s social security number, occupation, employer, and immigration status are not required and should not be recorded.', 'CA Government Code Section 8206, CA Secretary of State Notary Public Handbook (2025), Section 6'),

(6, 'What type of journal format is acceptable for a California notary?', ARRAY['A loose-leaf binder with sequentially numbered pages added by the notary', 'A permanently bound, pre-numbered paper journal, or an authorized tamper-evident electronic journal', 'Any notebook the notary finds convenient', 'A computer spreadsheet maintained by the notary''s employer'], 1, 'California law requires either a permanently bound paper journal with pre-numbered pages or a tamper-evident electronic journal authorized by the Secretary of State. Loose-leaf binders, standard notebooks, and employer-maintained spreadsheets without proper authorization do not meet statutory requirements.', 'CA Government Code Section 8206, CA Secretary of State Notary Public Handbook (2025), Section 6'),

(6, 'If a blank space is left on a line in a journal entry, what should the notary do?', ARRAY['Leave it blank—it does not matter', 'Fill it with irrelevant information to close the space', 'Draw a line through the blank space before proceeding to the next entry', 'Write "N/A" in every blank space'], 2, 'The notary should draw a line through any blank space within or after an entry before proceeding to the next entry. This prevents anyone from later adding unauthorized information to the journal entry. Drawing a line through blank spaces preserves the integrity of the journal.', 'CA Secretary of State Notary Public Handbook (2025), Section 6'),

(6, 'A notary resigns from their job. The employer paid for the notary''s journal and demands the journal be left with the office. What is the correct legal position?', ARRAY['The notary must leave the journal since the employer paid for it', 'The notary must leave a copy but keep the original', 'The notary must retain the original journal because it belongs to the notary, regardless of who paid for it', 'The employer and notary must split custody based on their employment agreement'], 2, 'The journal is the notary''s property and responsibility. Even if the employer paid for it, the law requires the notary to maintain exclusive custody and control at all times. The notary must take the journal when leaving employment. The employer has no legal right to retain the original, and the notary is not required to leave a copy.', 'CA Government Code Section 8206, CA Secretary of State Notary Public Handbook (2025), Section 6'),

(6, 'Which statement about electronic journals is correct?', ARRAY['Any software program the notary finds is acceptable', 'The electronic journal must be authorized by the Secretary of State and be tamper-evident', 'Electronic journals are not permitted in California under any circumstances', 'Electronic journals may be used but never for real property documents'], 1, 'A California notary may use an electronic journal only if the specific system has been authorized by the Secretary of State and is tamper-evident (designed so that any alteration, deletion, or unauthorized entry is detectable). The notary may not simply use any software or spreadsheet. Electronic journals are permitted for all types of documents, including real property documents.', 'CA Secretary of State Notary Public Handbook (2025), Section 6'),

(6, 'A signer asks the notary to record their thumbprint in the journal even though the document is not a deed. What should the notary do?', ARRAY['Refuse because thumbprints are strictly limited to deed-related documents', 'Record the thumbprint as requested; the deed requirement is a minimum, not a prohibition on additional records', 'Record the thumbprint only if the notary charges an additional fee', 'Refuse because recording unnecessary biometric data violates privacy laws'], 1, 'The statutory requirement for a thumbprint applies to deeds and other real property instruments. However, the notary is not prohibited from recording a thumbprint for other documents if the signer requests it. The deed requirement is a statutory minimum, not a maximum. The notary should not, however, require a thumbprint for non-deed documents.', 'CA Secretary of State Notary Public Handbook (2025), Section 6'),

(6, 'If a notary loses their journal, what immediate step should they take?', ARRAY['Do nothing—a lost journal is the signers'' problem', 'Notify the Secretary of State of the loss as soon as reasonably possible', 'Simply start a new journal without reporting the loss', 'Report the loss to the local police and take no further action'], 1, 'If a notary''s journal is lost, stolen, or destroyed, the notary should notify the Secretary of State as soon as reasonably possible. The journal contains sensitive personal information about signers, and its loss has potential privacy and security implications. The notary should document the circumstances of the loss and take reasonable steps to recover the journal.', 'CA Secretary of State Notary Public Handbook (2025), Section 6');

-- ============================================
-- QUESTIONS: Chapter 7 (Ethics and Legal Responsibilities) — 14 questions
-- ============================================

INSERT INTO questions (chapter_id, question, options, correct_index, explanation, source_ref) VALUES
(7, 'A notary public is also a real estate agent. A client is closing a real estate deal in which the notary will receive a commission. The client asks the notary to notarize the closing documents. What should the notary do?', ARRAY['Proceed with the notarization since they are also a real estate professional', 'Notarize the documents but waive the notary fee to avoid a conflict', 'Decline because the notary has a direct financial interest in the transaction', 'Notarize the documents but disclose the conflict in the journal'], 2, 'The notary has a direct financial interest in the real estate transaction because they will earn a real estate commission from the closing. This creates a statutory conflict of interest, and the notary must decline to notarize the documents. Waiving the notary fee does not cure the conflict. Disclosure in the journal does not make the notarization lawful.', 'CA Government Code Section 8224, CA Secretary of State Notary Public Handbook (2025), Section 7'),

(7, 'Which of the following acts is a California notary prohibited from performing?', ARRAY['Administering an oath to a witness', 'Notarizing a document in which the notary is a named beneficiary', 'Taking an acknowledgment for a stranger with valid ID', 'Making a journal entry at the time of the notarial act'], 1, 'A notary is prohibited from notarizing any document in which they have a direct financial or beneficial interest. Being a named beneficiary creates such an interest. Administering oaths, taking acknowledgments for strangers with valid ID, and making journal entries are all proper acts within a notary''s authority.', 'CA Government Code Sections 8224-8225, CA Secretary of State Notary Public Handbook (2025), Section 7'),

(7, 'A signer presents a document to be notarized, but several key fields—including a dollar amount and a property address—are left blank. The signer says, "Don''t worry, someone else will fill those in later." What should the notary do?', ARRAY['Notarize the document and note the blanks in the journal', 'Notarize the document but fill in the blanks before notarizing', 'Refuse to notarize the document until all blank spaces are filled in', 'Notarize only the signature page and leave the rest to others'], 2, 'A notary must never notarize a document with blank spaces, regardless of the signer''s assurances. The notary should refuse to proceed until the signer fills in all blank fields. The notary must not fill in the blanks themselves (that could constitute UPL or document preparation). Notarizing only the signature page is improper. Noting blanks in the journal does not make the notarization lawful.', 'CA Secretary of State Notary Public Handbook (2025), Section 7'),

(7, 'What is the unauthorized practice of law (UPL) as it relates to notaries public?', ARRAY['A notary performing notarial acts without a current commission', 'A notary giving legal advice, recommending documents, or explaining legal effects of documents', 'A notary charging more than the statutory maximum fee', 'A notary refusing to notarize documents for particular signers'], 1, 'Unauthorized practice of law (UPL) refers specifically to a person who is not a licensed attorney engaging in activities reserved for attorneys, such as giving legal advice, recommending which documents to use, explaining a document''s legal effect, or representing someone in a legal proceeding. Notaries who are not attorneys are strictly limited to witnessing signatures and administering oaths.', 'CA Government Code Section 8223, CA Secretary of State Notary Public Handbook (2025), Section 7'),

(7, 'A Spanish-speaking client visits a California notary and asks for help from a "notario publico." What concern should this raise for the notary?', ARRAY['None—"notario publico" is just the Spanish translation of "notary public."', 'The notary should be concerned because in many Latin American countries, a "notario publico" is a licensed attorney, and the notary must clarify they are not an attorney and cannot provide legal services', 'The notary must speak Spanish to serve the client', 'The notary should refer the client to immigration authorities'], 1, 'In many Latin American countries, a "notario publico" is a highly trained legal professional akin to an attorney, with far greater authority than a U.S. notary public. California law prohibits notaries from using the term "notario publico." When approached by such a client, the notary must clearly communicate that they are not an attorney and cannot provide legal advice or services.', 'CA Government Code Section 8228.1, CA Secretary of State Notary Public Handbook (2025), Section 7'),

(7, 'A notary public is approached by someone who asks the notary to complete immigration forms for a fee. The notary is not an attorney. Is this permissible?', ARRAY['Yes, if the notary is familiar with immigration procedures', 'Yes, as long as the notary does not charge more than the statutory notary fee', 'No, non-attorney notaries generally cannot assist with immigration paperwork under California law', 'Yes, if the notary registers with the Secretary of State as an immigration consultant'], 2, 'Non-attorney notaries are generally prohibited from assisting with immigration paperwork under California law. Providing immigration-related services when not a qualified attorney or accredited representative is both a violation of notary law and potentially federal immigration law. The prohibition exists regardless of the fee charged or the notary''s familiarity with immigration procedures.', 'CA Government Code Section 8228.1, CA Secretary of State Notary Public Handbook (2025), Section 7'),

(7, 'What is the relationship between the $15,000 surety bond and the notary''s personal liability?', ARRAY['The bond eliminates the notary''s personal liability entirely', 'If the surety pays a claim, the notary must reimburse the surety company in full', 'The bond only covers claims made by the state, not by private individuals', 'The bond serves as insurance that pays on the notary''s behalf without any repayment obligation'], 1, 'The surety bond is not insurance for the notary. If the surety company pays a claim to a member of the public, the notary is personally obligated to reimburse the surety in full, including any associated costs and attorneys'' fees. The bond protects the public by providing a source of funds for claims; it does not shield the notary from personal liability.', 'CA Government Code Sections 8212-8214, CA Secretary of State Notary Public Handbook (2025), Section 7'),

(7, 'A notary is asked to notarize their spouse''s signature on a deed transferring property that was purchased during the marriage (community property). Can the notary proceed?', ARRAY['Yes, because notarizing for a spouse is not explicitly prohibited by statute', 'No, because notarizing a document involving community property creates a direct financial interest for the notary', 'Yes, but only if the notary does not charge a fee', 'Yes, if the spouse presents valid identification'], 1, 'Although notarizing for a spouse is not automatically prohibited, the notary has a community property interest in the property being transferred. This creates a direct financial interest, which is a statutory conflict. The notary should decline. Even if no fee is charged and valid ID is presented, the direct financial interest remains disqualifying.', 'CA Government Code Section 8224, CA Secretary of State Notary Public Handbook (2025), Section 7'),

(7, 'A notary knowingly certifies that a person personally appeared and executed a document when in fact that person was never present. What potential penalties does this notary face?', ARRAY['No penalty—the notary made a simple mistake', 'A small administrative fine of up to $50', 'Civil penalties up to $1,500 per violation plus potential criminal prosecution for false certification', 'Mandatory re-taking of the notary examination'], 2, 'False certification of personal appearance is one of the most serious notary violations. Civil penalties of up to $1,500 per violation may be imposed, and criminal prosecution for a misdemeanor or even a felony may follow depending on the circumstances. The Secretary of State may also revoke or suspend the notary''s commission. This is not a minor mistake.', 'CA Secretary of State Notary Public Handbook (2025), Section 7'),

(7, 'An employer insists that a notary employee notarize a document in which the employer will benefit, even though the signer is not present. The employer claims they will take responsibility. What should the notary do?', ARRAY['Notarize the document as instructed by the employer', 'Notarize the document but make a journal note that the employer directed the act', 'Refuse—the notary is personally responsible for compliance with notary law regardless of employer pressure', 'Resign immediately without explanation'], 2, 'A notary is personally and individually responsible for complying with notary law, regardless of any pressure, instructions, or demands from an employer. The employer cannot "take responsibility" for a violation of notary law. The notary must refuse. While resignation may be an option, the immediate duty is to refuse the unlawful act.', 'CA Secretary of State Notary Public Handbook (2025), Section 7'),

(7, 'Which of the following constitutes a conflict of interest for a notary?', ARRAY['Notarizing a document for a stranger who presents valid identification', 'Notarizing a power of attorney in which the notary is named as the attorney-in-fact', 'Notarizing a document for a neighbor who the notary does not know well', 'Notarizing a document for someone of a different nationality'], 1, 'A notary who is named as attorney-in-fact in a power of attorney has a direct beneficial interest in that document and must not notarize it. Notarizing for strangers with valid ID is the notary''s public duty. Notarizing for a neighbor without personal knowledge (using ID instead) is proper. Nationality is irrelevant to the notary''s obligations.', 'CA Government Code Section 8224, CA Secretary of State Notary Public Handbook (2025), Section 7'),

(7, 'A notary is asked, "What does this power of attorney do?" The notary is not an attorney. What is the appropriate response?', ARRAY['Explain what a power of attorney generally does based on the notary''s experience', 'Explain that the notary is not an attorney and cannot provide legal advice or explain legal effects of documents', 'Summarize the document in plain language for the signer', 'Tell the signer the document appears to be fine and they should sign it'], 1, 'The notary must not provide any explanation of what a legal document does, even if they think they understand it. The correct response is to disclose that the notary is not an attorney and cannot provide legal advice. The notary should suggest the signer consult with an attorney, the document preparer, or the party who provided the document.', 'CA Government Code Section 8223, CA Secretary of State Notary Public Handbook (2025), Section 7'),

(7, 'What happens if the surety bond of a California notary is cancelled mid-term?', ARRAY['The notary continues to operate but must file a new bond within 90 days', 'The commission is automatically suspended and the notary must stop performing notarial acts until a new bond is filed', 'The notary is immediately subject to criminal prosecution', 'The commission is permanently revoked and cannot be reinstated'], 1, 'If the surety bond is cancelled, the notary''s commission is automatically suspended. The notary must immediately cease performing notarial acts. The commission is not permanently revoked—the notary may file a new bond to have the commission reinstated. Criminal prosecution does not automatically follow bond cancellation, though performing acts during suspension could lead to liability.', 'CA Government Code Section 8213, CA Secretary of State Notary Public Handbook (2025), Section 7'),

(7, 'A notary has completed a notarial act and the signer has left. The notary then realizes the certificate contains an error. What should the notary do?', ARRAY['Nothing—the act is complete and cannot be changed', 'Contact the signer to return for a corrected certificate; do not alter the existing one', 'Cross out the error on the certificate and initial the change', 'Complete a new certificate with the correct information and attach it'], 1, 'Once an error is discovered on a completed notarial certificate after the signer has left, the notary should contact the signer to return. The signer typically must be present for the correction. The notary should not alter the existing certificate after the fact, and generally should not simply create a new certificate without the signer reappearing. If the signer cannot return, the notary should document the situation in the journal.', 'CA Secretary of State Notary Public Handbook (2025), Section 7');
